package com.bank.qa.autodecide;

// A test described by the traits that drive the automate/manual decision.
class CandidateTest {
    final String name;
    final boolean repetitive;      // runs on every build?
    final boolean stable;          // requirements/UI stable?
    final boolean businessCritical;// e.g. transfer/payment
    final boolean dataDriven;      // same steps, many data rows
    final boolean needsJudgement;  // visual/UX subjective
    final boolean oneOff;          // runs once (migration/release check)

    CandidateTest(String name, boolean repetitive, boolean stable, boolean businessCritical,
                  boolean dataDriven, boolean needsJudgement, boolean oneOff) {
        this.name = name; this.repetitive = repetitive; this.stable = stable;
        this.businessCritical = businessCritical; this.dataDriven = dataDriven;
        this.needsJudgement = needsJudgement; this.oneOff = oneOff;
    }
}
