package com.bank.qa.autodecide;

import java.util.logging.Logger;

// Recommends AUTOMATE or MANUAL with the reason behind the decision.
class AutomationAdvisor {
    private static final Logger log = Logger.getLogger(AutomationAdvisor.class.getName());

    String recommend(CandidateTest t) {
        // Hard MANUAL signals override: judgement and volatility make automation a trap.
        if (t.needsJudgement) {
            log.warning(t.name + " -> MANUAL (needs human judgement: automation cannot assess UX)");
            return "MANUAL";
        }
        if (!t.stable) {
            log.warning(t.name + " -> MANUAL for now (volatile requirements -> brittle tests; "
                + "defer automation until it stabilizes)");
            return "MANUAL";
        }
        if (t.oneOff) {
            log.warning(t.name + " -> MANUAL (one-off: automation cost will not pay back)");
            return "MANUAL";
        }
        // Strong AUTOMATE signals
        if (t.repetitive || t.businessCritical || t.dataDriven) {
            log.info(t.name + " -> AUTOMATE (stable + "
                + (t.businessCritical ? "business-critical " : "")
                + (t.repetitive ? "repetitive " : "")
                + (t.dataDriven ? "data-driven " : "") + "=> high payback)");
            return "AUTOMATE";
        }
        log.info(t.name + " -> MANUAL (low run-frequency, limited payback)");
        return "MANUAL";
    }
}
