package com.bank.qa.autodecide;

import java.util.List;
import java.util.logging.*;

public class AutomationDecisionDemo {
    private static final Logger log = Logger.getLogger(AutomationDecisionDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new AutoLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        AutomationAdvisor advisor = new AutomationAdvisor();

        List<CandidateTest> candidates = List.of(
            //                 name                         rep   stab  crit  data  judge oneOff
            new CandidateTest("transfer-regression",        true, true, true, false,false,false),
            new CandidateTest("interest-calc-100-rows",     true, true, true, true, false,false),
            new CandidateTest("new-rewards-screen (weekly)",false,false,false,false,true, false),
            new CandidateTest("statement-layout-looks-good",false,true, false,false,true, false),
            new CandidateTest("one-time-data-migration-check",false,true,true, false,false,true),
            new CandidateTest("payment-smoke",              true, true, true, false,false,false)
        );

        log.info("=== Automate vs manual decisions ===");
        int auto = 0;
        for (CandidateTest c : candidates) {
            if (advisor.recommend(c).equals("AUTOMATE")) auto++;
        }
        log.info("Recommended AUTOMATE: " + auto + "/" + candidates.size()
            + " (NOT everything — that would build a brittle, costly suite)");
    }
}

// ─── Would be in AutoLogFormatter.java in a real project ───
class AutoLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
